nit: Feels like a helper could have deduplicated these edge case tests quite a bit, but not a blocker for me. Basically this (untested):

```
static void ec_pubkey_parse_expect_fail(const unsigned char *input, size_t inputlen) {
    secp256k1_pubkey pubkey;
    secp256k1_ge ge;
    memset(&pubkey, 0xfe, sizeof(pubkey));
    SECP256K1_CHECKMEM_UNDEFINE(&pubkey, sizeof(pubkey));
    CHECK(secp256k1_ec_pubkey_parse(CTX, &pubkey, input, inputlen) == 0);
    SECP256K1_CHECKMEM_CHECK(&pubkey, sizeof(pubkey));
    CHECK_ILLEGAL(CTX, secp256k1_pubkey_load(CTX, &ge, &pubkey));
}
```
